var minimumDistance = function (word) {
    let res = Infinity;

    const dfs = (index, left, right, cost) => {
        if (index === word.length) {
            res = Math.min(res, cost);
            return;
        }

        dfs(index + 1, word[index], right, cost + getMoveCost(left, word[index]));
        dfs(index + 1, left, word[index], cost + getMoveCost(right, word[index]));
    };
    dfs(0, '', '', 0);

    return res;
};

const getMoveCost = (from, to) => {
    if (!from) return 0;

    const [fromX, fromY] = map[from];
    const [toX, toY] = map[to];

    return Math.abs(fromX - toX) + Math.abs(fromY - toY);
};

const map = {
    A: [0, 0],
    B: [0, 1],
    C: [0, 2],
    D: [0, 3],
    E: [0, 4],
    F: [0, 5],
    G: [1, 0],
    H: [1, 1],
    I: [1, 2],
    J: [1, 3],
    K: [1, 4],
    L: [1, 5],
    M: [2, 0],
    N: [2, 1],
    O: [2, 2],
    P: [2, 3],
    Q: [2, 4],
    R: [2, 5],
    S: [3, 0],
    T: [3, 1],
    U: [3, 2],
    V: [3, 3],
    W: [3, 4],
    X: [3, 5],
    Y: [4, 0],
    Z: [4, 1],
};

/**
 * @param {string} word
 * @return {number}
 */
var minimumDistance = function (word) {
    const n = word.length;
    const getDistance = (p, q) => {
        const x1 = Math.floor(p / 6),
            y1 = p % 6;
        const x2 = Math.floor(q / 6),
            y2 = q % 6;
        return Math.abs(x1 - x2) + Math.abs(y1 - y2);
    };

    const dp = Array.from({ length: n }, () => Array.from({ length: 26 }, () => Math.floor(Number.MAX_SAFE_INTEGER / 2)));

    for (let j = 0; j < 26; j++) {
        dp[0][j] = 0;
    }

    for (let i = 1; i < n; i++) {
        const cur = word.charCodeAt(i) - 65;
        const prev = word.charCodeAt(i - 1) - 65;
        const d = getDistance(prev, cur);

        for (let j = 0; j < 26; j++) {
            dp[i][j] = Math.min(dp[i][j], dp[i - 1][j] + d);

            if (prev === j) {
                for (let k = 0; k < 26; k++) {
                    const d0 = getDistance(k, cur);
                    dp[i][j] = Math.min(dp[i][j], dp[i - 1][k] + d0);
                }
            }
        }
    }

    let ans = Math.floor(Number.MAX_SAFE_INTEGER / 2);

    for (let j = 0; j < 26; j++) {
        ans = Math.min(ans, dp[n - 1][j]);
    }

    return ans;
};
